fun AppLanguage.t(key: String): String = when (this) {
    AppLanguage.ENGLISH -> english[key]
    AppLanguage.FRENCH -> french[key]
    AppLanguage.GERMAN -> german[key]
    AppLanguage.RUSSIAN -> russian[key]
    AppLanguage.PORTUGUESE -> portuguese[key]
    AppLanguage.PORTUGUESE_BRAZIL -> portugueseBrazil[key]
    AppLanguage.SPANISH -> spanish[key]
    AppLanguage.CHINESE -> chinese[key]
    AppLanguage.CHINESE_TRADITIONAL -> chineseTraditional[key]
    AppLanguage.ARABIC -> arabic[key]
    AppLanguage.JAPANESE -> japanese[key]
    AppLanguage.KOREAN -> korean[key]
} ?: english[key] ?: key
